#!/usr/bin/env node
// SPDX-License-Identifier: AGPL-3.0-only
// The look-alike names hint (D-21) of the playground against the language
// server's.
//
//   node tests/test_lookalike.mjs
//
// Two editors give the hint: the language server, with the `unicode-security`
// crate, and the playground's problems panel through `confusableHints`, with
// src/zymbol/skeleton.js, generated by tools/gen_skeleton.mjs. They agree only
// while their data is the same version. So this writes one document of 3000
// names built out of characters confusables.txt maps — and the letters they are
// taken for, from a fixed seed — opens it in the real server, and requires the
// same warnings, line for line and word for word.
//
// ZYMBOL_LSP_BIN picks the server (default: ../interpreter/target/release/zymbol-lsp,
// then `zymbol-lsp` on PATH). Exit 2 when there is none.

import { spawn } from 'child_process';
import { existsSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const HERE = dirname(fileURLToPath(import.meta.url));
const { confusableHints, isIdentStart, isIdentContinue } = await import('../src/zymbol/zymbol.js');
const { UNICODE_VERSION } = await import('../src/zymbol/skeleton.js');

let bin = process.env.ZYMBOL_LSP_BIN;
if (!bin) {
  const built = join(HERE, '../../interpreter/target/release/zymbol-lsp');
  bin = existsSync(built) ? built : 'zymbol-lsp';
}

// Letters and their look-alikes in several scripts, math alphabets, marks, a
// default-ignorable joiner, and digits taken for letters.
const POOL = [
  'a', 'а', 'ɑ', 'α', 'e', 'е', 'ҽ', 'o', 'о', 'ο', 'օ', '0', 'p', 'р', 'ρ', 'c', 'с', 'ϲ', 'x', 'х',
  'y', 'у', 'i', 'і', 'ı', 'l', '1', 'I', 'Ӏ', 'ǀ', 'r', 'n', 'm', 'E', 'Ε', 'Е', 'H', 'Η', 'Н',
  'B', 'В', 'Β', 'K', 'К', 'Κ', 'M', 'М', 'Μ', 'T', 'Т', 'Τ', '𝐚', '𝖺', '𝗮', 'ａ', 'ｅ', 'ᴀ',
  '́', '̀', '‍', 'é', 'ё', 'ë', 'ꮪ', 'Ꮪ', 'ꭺ', 'Ꭺ', 'ա', 'ս', 'g', 'ɡ', 'ց',
].filter(c => isIdentContinue(c));
let seed = 2026;
// A 32-bit LCG in integer arithmetic, read from its high bits: the product in
// doubles passed 2^53 and lost the low bits, so every draw was a multiple of 8.
const rand = n => { seed = (Math.imul(seed, 1103515245) + 12345) >>> 0; return (seed >>> 8) % n; };
const lines = [];
for (let i = 0; i < 3000; i++) {
  let s = 'q';
  for (let k = 1 + rand(3); k > 0; k--) s += POOL[rand(POOL.length)];
  if (s.endsWith('‍')) s += 'a';
  lines.push(`${s} = 1`);
}
const doc = lines.join('\n') + '\n';
if (!lines.every(l => isIdentStart(l[0]))) throw new Error('a name does not start a name');

const js = confusableHints(doc).filter(d => d.code === 'W_CONFUSABLE_NAME')
  .map(d => `${d.line}: ${d.message}`);

// ── the language server ──────────────────────────────────────────────────────
function lsp() {
  return new Promise((resolve, reject) => {
    const p = spawn(bin, [], { stdio: ['pipe', 'pipe', 'ignore'] });
    p.on('error', reject);
    let buf = Buffer.alloc(0);
    const send = o => {
      const b = Buffer.from(JSON.stringify({ jsonrpc: '2.0', ...o }));
      p.stdin.write(`Content-Length: ${b.length}\r\n\r\n`);
      p.stdin.write(b);
    };
    const uri = 'file:///tmp/lookalike.zy';
    const timer = setTimeout(() => { p.kill(); reject(new Error('no diagnostics within 60 s')); }, 60000);
    p.stdout.on('data', chunk => {
      buf = Buffer.concat([buf, chunk]);
      for (;;) {
        const head = buf.indexOf('\r\n\r\n');
        if (head < 0) return;
        const len = Number(/Content-Length: (\d+)/i.exec(buf.slice(0, head).toString())?.[1]);
        if (buf.length < head + 4 + len) return;
        const msg = JSON.parse(buf.slice(head + 4, head + 4 + len).toString());
        buf = buf.slice(head + 4 + len);
        if (msg.id === 1) {
          send({ method: 'initialized', params: {} });
          send({ method: 'textDocument/didOpen', params: { textDocument: { uri, languageId: 'zymbol', version: 1, text: doc } } });
        } else if (msg.method === 'textDocument/publishDiagnostics' && msg.params.uri === uri) {
          clearTimeout(timer);
          send({ id: 2, method: 'shutdown' });
          send({ method: 'exit' });
          resolve(msg.params.diagnostics);
        }
      }
    });
    send({ id: 1, method: 'initialize', params: { processId: process.pid, rootUri: null, capabilities: {} } });
  });
}

let diagnostics;
try { diagnostics = await lsp(); } catch (e) {
  console.error(`test_lookalike: could not run ${bin}: ${e.message}`);
  process.exit(2);
}
const rust = diagnostics.filter(d => d.code === 'confusable-name')
  .sort((a, b) => a.range.start.line - b.range.start.line)
  .map(d => `${d.range.start.line + 1}: ${d.message}`);

console.log(`\nskeleton.js (confusables ${UNICODE_VERSION}) against ${bin}`);
const bad = rust.findIndex((l, i) => l !== js[i]);
if (rust.length === js.length && bad === -1 && rust.length > 0) {
  console.log(`  ok   ${lines.length} names, ${rust.length} that look like an earlier one, warned alike`);
  console.log('\nall passed');
  process.exit(0);
}
if (rust.length !== js.length) console.log(`  FAIL ${rust.length} warnings from the server, ${js.length} from the playground`);
if (bad !== -1) console.log(`  FAIL first difference:\n    server     ${rust[bad]}\n    playground ${js[bad]}`);
console.log('  regenerate with tools/gen_skeleton.mjs and the data of unicode-security\'s UNICODE_VERSION');
process.exit(1);
